/** evening_briefing: one spoken paragraph, generated by Amazon Bedrock when configured. */
import type { McpServer } from "@modelcontextprotocol/server";
import { z } from "zod";
import { forecast } from "../forecast.js";
import { assess, type SessionContext } from "../situation.js";
import * as bedrock from "../bedrock.js";

/** The language model behind the briefing; injectable so the fallback path is testable without AWS. */
export interface Summarizer { enabled: boolean; summarize(text: string): Promise<string> }
const defaultSummarizer: Summarizer = { enabled: bedrock.bedrockEnabled, summarize: bedrock.summarize };

export function registerBriefingTools(server: McpServer, ctx: SessionContext, llm: Summarizer = defaultSummarizer): void {
  server.registerTool("evening_briefing", {
    title: "Evening power briefing",
    // Small models decide from this text alone. Name the phrasings that should trigger it.
    description: "ALWAYS use this for any request for a briefing, summary, outlook, report or 'how are we for tonight' about power or the battery. Returns one spoken paragraph — overnight battery outlook, expected grid windows, what to avoid — computed from the forecast (never guessed) and phrased by Amazon Bedrock when configured.",
    inputSchema: z.object({}),
    annotations: { readOnlyHint: true },
  }, async () => {
    const { t, h, profile, input } = await assess(ctx);
    const f = forecast(input);
    const gridOn = input.gridForecast.filter(Boolean).length;
    const heavy = h.appliances.filter((a) => a.watts >= 1000).map((a) => a.name);
    const facts = [
      `Battery ${t.soc_pct}%, reserve ${profile.reserveSocPct}%.`,
      f.hitsFloor ? `Reserve reached in ${f.hoursToFloor!.toFixed(1)} h; lowest ${f.minSocPct}%.` : `Battery stays above reserve overnight; lowest ${f.minSocPct}%.`,
      gridOn ? `Grid expected on in ${gridOn} of the next 24 hours.` : `No grid expected tonight.`,
      h.appliances.length ? `Known heavy appliances: ${heavy.join(", ") || "none"}.` : "",
    ].filter(Boolean).join(" ");
    if (!llm.enabled) return { content: [{ type: "text", text: facts }], _meta: { bedrock: false } };
    try {
      const spoken = (await llm.summarize(facts)).trim();
      // An empty or absurdly short reply means the model returned nothing useful; the facts are better than silence.
      if (spoken.length < 20) throw new Error("empty response");
      return { content: [{ type: "text", text: spoken }], _meta: { bedrock: true } };
    } catch (e) {
      // Bedrock being down, throttled, or misconfigured must not take the briefing with it.
      const reason = (e as Error).message;
      console.error(`[briefing] Bedrock failed (${reason}); returning plain facts`);
      return { content: [{ type: "text", text: facts }], _meta: { bedrock: false, bedrockError: reason } };
    }
  });
}
